const dialog=document.querySelector('dialog');document.querySelectorAll('[data-contact]').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.querySelector('.copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('haidernotfound');document.querySelector('.copy-status').textContent='Copied! Add haidernotfound on Discord.'}catch{document.querySelector('.copy-status').textContent='Username: haidernotfound'}});document.querySelector('#year').textContent=new Date().getFullYear();const past=[['Lurrn Elytra Tierlist','Moderator & Tester','1,200+ Discord members'],['ChickenCraft','Helper','500–600+ average players'],['Rtrix.eu','CheatHunter · PC Checker','200+ average players'],['MineBoxx','Staff Manager','60+ average players'],['CompSMP','Admin · PC Checker','50+ average players'],['BlitzNetwork · Second tenure','Admin · Media Manager','40+ average players'],['BlitzNetwork · First tenure','Co Owner','40+ average players']];document.querySelector('#past').innerHTML=past.map((p,i)=>`<article><span class="rownum">0${i+1}</span><div><h3>${p[0]}</h3><p>${p[1]}</p></div><span class="rowdetail">${p[2]}</span><span class="arrow">↗</span></article>`).join('');const tabs=[...document.querySelectorAll('[data-tab]')];function activate(t){tabs.forEach(b=>{b.setAttribute('aria-selected',b===t);b.tabIndex=b===t?0:-1;document.getElementById(b.dataset.tab).hidden=b!==t})}tabs.forEach((t,i)=>{t.addEventListener('click',()=>activate(t));t.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=tabs[e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+1)%tabs.length];activate(next);next.focus()}})});activate(tabs[0]);if('IntersectionObserver'in window){document.body.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e))}let ticking=false;window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=(max?scrollY/max*100:0)+'%';ticking=false});ticking=true}},{passive:true});const visual=document.querySelector('.visual');if(matchMedia('(pointer:fine) and (prefers-reduced-motion:no-preference)').matches){visual.addEventListener('pointermove',e=>{const r=visual.getBoundingClientRect();visual.style.transform=`rotateX(${-(e.clientY-r.top-r.height/2)/40}deg) rotateY(${(e.clientX-r.left-r.width/2)/40}deg)`});visual.addEventListener('pointerleave',()=>visual.style.transform='')}
